// The feed's updates: the steps of the work, put to a model as a log divided into stretches, and its reply
// read back as one short account of each stretch, the way a match is told as it goes. Pure: the model call is
// the hooks module's; this makes the prompt and reads the answer.

import type { Beat, Item, Trail } from '../types'
import { clean, clip, MAX_BEATS, SENT, waitsOf, workCount, workLine } from './trail.ts'

/** Steps to write updates for. */
export type Job = {
  /** The steps it covers, which are marked once the updates are in. */
  ids: string[]
  /** The log's numbered stretches, by number: each the step its update is tied to, the last of the stretch. */
  slots: Item[]
  /** The log, when a model is to read it. */
  prompt: string
  /** The updates, when the work is too slight to need a model: an exchange with no work in it. */
  local?: Beat[]
  /** The log runs to the latest of the session: only then does it show what is left waiting on the person. */
  isLatest: boolean
  /** The things still waiting on the person that the log names, in the order it marks them w1, w2 and so on. */
  open: string[]
  /** The pictures and files without a caption that the log names, in the order it marks them p1, p2 and so on. */
  pics: string[]
}

/** Characters of log put to the model at once. */
const LOG_MAX = 9000
/** Characters of the newest turns told again when the person asks for the transcript to be read back: under one log's worth. */
const RETOLD_MAX = 6000
/** Steps to a stretch: each stretch is told in one update, so this is how often a long run is told of. */
const STRETCH_STEPS = 4
const UPDATE_MAX = 420
/** Actions to a stretch, and the length of one: an update is a few short lines, not a paragraph. */
const ACTIONS_MOST = 3
const ACTION_MAX = 90
/** What stands in for an exchange with no work in it: the start of the answer. */
const ANSWER_SHOWN = 110
/** Things one reply may leave waiting on the person, the length of each, and how many still waiting are put to the model. */
const WAITS_MOST = 3
const WAIT_MAX = 200
const OPEN_MOST = 8
/** Commands and links one thing waiting may carry, and the length of one. */
const REFS_MOST = 4
const REF_MAX = 240
/** Pictures one log asks captions for, and the length of a caption. */
const PICS_MOST = 12
const CAPTION_MAX = 320
const STILL_WAITING = 'STILL WAITING ON THE PERSON FROM BEFORE THIS LOG:'
/** What in an answer with no work in it says something may be left with the person: it is then put to a model like any other. */
const LEFT_WITH_THEM = /\?|\b(?:waits?|waiting|blocked) on you\b|\bneeds? you(?:r)?\b|\byou(?:'ll| will)? (?:need|have) to\b|\b(?:once|until|after) you\b|\byour (?:call|go-ahead|approval|answer|decision|choice|pick|sign-off)\b|\b(?:let|tell) me\b|\bsay which\b|\bup to you\b|\bconfirm\b/i

export const SYSTEM = [
  'You write the activity feed of a coding session between a person and Claude, an AI coding agent: a terse list of what was done, so the person can see what happened at a glance without reading the conversation.',
  '',
  'You are given a log of part of the session: what the person asked, then what Claude said and did, divided into numbered stretches marked [1], [2] and so on.',
  'For each stretch, write the things done in it that matter, as one to three actions. An action is a few words, eight at most, in the past tense, starting with a verb and naming the thing: "Fixed the scroll jump in the list", "Pushed the new look, 228 tests passing", "Opened PR 8", "Found the leak in the cache". Put the outcome or the number in it where there is one. Separate the actions of a stretch with " ; ".',
  'Only what was done or found. Leave out reading files, re-running commands, plans, explanations, what will be done next, and anything about how Claude went about it. No sentences, no "Claude" or "you" as the subject, no filler. Fewer actions is better: a stretch that did one thing gets one.',
  'Report only what the log shows was done or found. What the person asked for is there so you know what the work was for: never report it as done unless the log shows it.',
  '',
  'Reply with one line per stretch:',
  'N|action ; action',
  'where N is the number of the stretch.',
  '',
  'Then, only if the end of the log leaves something waiting on the person, add one line for each such thing:',
  'wait|N|what they are to do, in at most twenty words ::: command or link ;; command or link',
  'where N is the stretch that left it waiting. Something waits on the person when a piece of the work cannot go on, or cannot be finished, until they act: a command only they can run, a sign-in or a permission, an approval, a choice or a question Claude put to them, something to try and report back on. Begin with the verb and say what it unblocks ("Run `gh auth refresh -s workflow` so the packaging branch can be pushed"). An offer of more work, a suggestion, and anything Claude will do by itself are not waiting on them, and most logs leave nothing waiting.',
  'After " ::: " give what they need to do it with, up to four, separated by " ;; ": the exact command to run, or the link to open (a pull request, a page, a dashboard). Copy each exactly from the log. Where the log names the thing but not the command, give the command only if it is the plain, standard one for that action and tool (merging pull request 13 with the GitHub CLI is "gh pr merge 13"); never guess at flags, names or addresses. With nothing to give, leave " ::: " out.',
  'The log may open with things still waiting on the person from before, marked w1, w2 and so on. Never write a wait line for one of those again. If the log shows that one of them was done or answered, or no longer matters, add a line:',
  'clear|w1',
  'with its mark.',
  '',
  'Then, for each picture or file the log marks p1, p2 and so on, add one line:',
  'pic|p1|what it shows and what it was for, in at most thirty words',
  'going only by what the log says around it: what the person said as they pasted it, what Claude said it saw in it, what Claude made or sent it for. You cannot see the picture, so never guess at what is in it: if the log does not say, leave the caption empty ("pic|p1|").',
  'Write nothing else.',
].join('\n')

const bearing = (item: Item): boolean => item.kind === 'ask' || item.kind === 'step' || item.kind === 'done'
const isStep = (item: Item): boolean => item.kind === 'step' || item.kind === 'done'

const beatAt = (item: Item, text: string): Beat => ({
  id: 'b:' + item.id,
  ref: item.id,
  turn: item.turn,
  at: item.at,
  kind: 'summary',
  title: clip(clean(text), UPDATE_MAX),
  detail: '',
  anchor: item.anchor,
  ...(item.alt ? { alt: item.alt } : {}),
})

/** Work too slight to need a model: something asked and answered with nothing done, or a command nothing followed. */
const slight = (items: Item[]): Beat[] | undefined => {
  const steps = items.filter(isStep)
  const worked = items.some(item => item.work !== undefined && workCount(item.work) > 0) || items.some(item => item.kind === 'shot')
  if (worked || steps.length > 1) return undefined
  const [answer] = steps
  // An answer that may leave something with the person is read by a model, which says what waits on them.
  if (answer && LEFT_WITH_THEM.test(answer.more ?? answer.line)) return undefined
  // The answer is the whole of what happened: its first sentence, kept short, is the update.
  return answer ? [beatAt(answer, clip(answer.line, ANSWER_SHOWN))] : []
}

/** A turn's steps as stretches, each to be told in one update; a lone last step joins the stretch before it. */
const stretchesOf = (items: Item[]): Item[][] => {
  const parts: Item[][] = [[]]
  let steps = 0
  for (const item of items) {
    if (isStep(item) && steps >= STRETCH_STEPS) {
      parts.push([])
      steps = 0
    }
    parts[parts.length - 1]!.push(item)
    if (isStep(item)) steps++
  }
  const last = parts[parts.length - 1]!
  if (parts.length > 1 && last.filter(isStep).length < 2) parts.splice(parts.length - 2, 2, [...parts[parts.length - 2]!, ...last])
  return parts.filter(part => part.length > 0)
}

/** How the log tells of a picture or a file, by where it came from; marked when a caption is wanted for it. */
const pictureText = (item: Item, mark: string): string => {
  const marked = mark ? `[${mark}] ` : ''
  const type = item.shot?.type ?? 'image'
  if (item.shot?.from === 'person') return `${marked}the person pasted a picture with what they asked`
  if (item.line.startsWith(SENT)) return `${marked}sent the person ${type === 'video' ? 'a video' : type === 'file' ? 'a file' : 'a picture'}: ${item.line.slice(SENT.length)}`
  if (type === 'link') return `${marked}published a page: ${item.line.replace(/^Published /, '')}`
  if (type === 'video') return `${marked}a command made a video: ${item.line}`
  return `${marked}looked at a picture: ${item.line}`
}

const entryText = (item: Item, isLast: boolean, mark = ''): string => {
  const did = item.work && workCount(item.work) > 0 ? ` [did: ${[...item.work.notes, workLine(item.work)].join('; ')}]` : ''
  if (item.kind === 'shot') return pictureText(item, mark)
  if (item.kind === 'ask') return `(before saying anything)${did}`
  const said = item.more ?? item.line
  return `${item.kind === 'done' && isLast ? 'final answer' : 'said'}: ${said}${did}`
}

const logOf = (turns: Item[][]): { prompt: string; slots: Item[]; pics: string[] } => {
  const slots: Item[] = []
  const pics: string[] = []
  const lines: string[] = []
  // An output nothing has said anything of yet is marked, for the model to say what the log tells of it. A picture
  // the person pasted, or one from before the session, is listed nowhere and gets no caption.
  const markOf = (item: Item): string => (item.kind === 'shot' && item.shot?.note === undefined && item.shot?.from === undefined && pics.length < PICS_MOST ? `p${pics.push(item.id)}` : '')
  for (const items of turns) {
    const ask = items.find(item => item.kind === 'ask')
    if (lines.length > 0) lines.push('')
    // A request whose first stretch is told already is there for what the work is about, not to be told again.
    lines.push(ask?.fed ? 'EARLIER THE PERSON ASKED (already told of: do not repeat it):' : lines.length === 0 ? 'THE PERSON ASKED:' : 'THEN THE PERSON ASKED:')
    lines.push(ask ? (ask.more ?? ask.line) : '(the work carried on from before)')
    lines.push(ask?.fed ? 'CLAUDE WENT ON:' : 'CLAUDE:')
    const shown = items.filter(item => bearing(item) || item.kind === 'shot').filter(item => item.kind !== 'ask' || (item.work !== undefined && workCount(item.work) > 0))
    for (const stretch of stretchesOf(shown)) {
      slots.push([...stretch].reverse().find(bearing) ?? stretch[stretch.length - 1]!)
      lines.push(`[${slots.length}]`)
      for (const item of stretch) lines.push(entryText(item, item === shown[shown.length - 1], markOf(item)))
    }
  }
  return { prompt: lines.join('\n'), slots, pics }
}

/**
 * The next steps worth writing updates for, newest first so what the person
 * sees on opening the pane is written before the history behind it: the
 * steps of a finished turn not yet told, or of a running one once a stretch
 * of them is there. Finished turns with little in them are taken together.
 */
export const nextJob = (trail: Trail, skipped: ReadonlySet<string> = new Set()): Job | null => {
  const byTurn = new Map<number, Item[]>()
  for (const item of trail.items) {
    if (item.kind === 'recap' || item.kind === 'compact') continue
    byTurn.set(item.turn, [...(byTurn.get(item.turn) ?? []), item])
  }
  const waiting: Item[][] = []
  for (const turn of [...byTurn.keys()].sort((a, b) => b - a)) {
    const items = byTurn.get(turn)!
    const isRunning = trail.isOpen && turn === trail.turn
    // The newest step of a running turn is still gathering its work; the rest can be told.
    const lastBearer = [...items].reverse().find(bearing)
    const open = items.filter(item => !item.fed && !skipped.has(item.id) && (!isRunning || item !== lastBearer))
    const fresh = open.filter(item => bearing(item) || item.kind === 'shot')
    if (fresh.filter(bearing).length === 0) continue
    if (isRunning && fresh.filter(isStep).length < STRETCH_STEPS) continue
    const stretch = [...(open.some(item => item.kind === 'ask') ? [] : items.filter(item => item.kind === 'ask')), ...open]
    if (waiting.length > 0 && logOf([...waiting, stretch]).prompt.length > LOG_MAX) break
    waiting.push(stretch)
    if (isRunning) break
  }
  if (waiting.length === 0) return null

  // Oldest first in the log, as it happened.
  waiting.reverse()
  const ids = waiting.flat().map(item => item.id)
  // Only a log that runs to the latest shows how things now stand: what is left with the person, and what no
  // longer is. One with something already told after it is history being caught up on.
  const last = Math.max(...waiting.flat().map(item => item.turn))
  const isLatest = !trail.items.some(item => item.turn > last && item.fed)
  const open = isLatest ? waitsOf(trail).slice(-OPEN_MOST) : []
  // While something waits on the person every exchange is read by a model: any of them may be where it was done.
  const isSlight = (items: Item[]): Beat[] | undefined => (open.length > 0 ? undefined : slight(items))
  const told = waiting.filter(items => isSlight(items) === undefined)
  const local = waiting.flatMap(items => isSlight(items) ?? [])
  if (told.length === 0) return { ids, slots: [], prompt: '', local, isLatest, open: [], pics: [] }
  const { prompt, slots, pics } = logOf(told)
  const still = open.length > 0 ? [STILL_WAITING, ...open.map((beat, index) => `w${index + 1}: ${beat.title}`), '', ''].join('\n') : ''
  return { ids, slots, prompt: still + clip(prompt, LOG_MAX * 2), ...(local.length > 0 ? { local } : {}), isLatest, open: open.map(beat => beat.id), pics }
}

/**
 * How many steps have no update and will get none unasked: those of turns
 * with something already told after them. They went by while the pane was
 * closed, and are history now that the latest is told.
 */
export const backlogOf = (trail: Trail): number => {
  const told = trail.items.reduce((latest, item) => (item.fed ? Math.max(latest, item.turn) : latest), -1)
  return trail.items.filter(item => isStep(item) && !item.fed && item.turn < told).length
}

/** The model's reply as updates: each line it wrote in the form asked for, tied to the last step of the stretch it numbers. */
export const parseBeats = (reply: string, job: Job): Beat[] => {
  const beats: Beat[] = []
  const told = new Set<number>()
  let waits = 0
  for (const raw of reply.split('\n')) {
    // Something left waiting on the person: tied to the stretch that left it, and listed apart until it is done.
    const wait = /^\s*[-*]?\s*wait\s*\|\s*\[?(\d+)\]?\s*\|\s*(.+?)\s*$/i.exec(raw)
    if (wait) {
      const left = job.slots[Number(wait[1]) - 1]
      const [said = '', withIt = ''] = wait[2]!.split(/\s+:::\s*/, 2)
      const what = clip(clean(said), WAIT_MAX)
      // What they need to do it with: commands to copy and links to open, as the model gave them.
      const refs = withIt
        .split(/\s*;;\s*/)
        .map(ref => clean(ref).replace(/^`+|`+$/g, ''))
        .filter(ref => ref.length >= 2 && ref.length <= REF_MAX)
        .slice(0, REFS_MOST)
      if (left && what.length >= 4 && waits < WAITS_MOST) beats.push({ ...beatAt(left, what), id: `w:${left.id}:${waits++}`, kind: 'waiting', ...(refs.length > 0 ? { refs } : {}) })
      continue
    }
    if (/^\s*[-*]?\s*(?:clear|pic)\s*\|/i.test(raw)) continue
    const found = /^\s*[-*]?\s*\[?(\d+)\]?\s*\|\s*(.+?)\s*$/.exec(raw)
    if (!found) continue
    const slot = Number(found[1])
    const at = job.slots[slot - 1]
    // The actions of the stretch, each kept short and on a line of its own.
    const actions = found[2]!
      .split(/\s+;\s+|\s*;\s*$/)
      .map(action => clip(clean(action).replace(/^[;\s]+|[.;,\s]+$/g, ''), ACTION_MAX))
      .filter(action => action.length >= 3)
      .slice(0, ACTIONS_MOST)
    // One update to a stretch; a number that names none, or a line left empty, says nothing.
    if (!at || told.has(slot) || actions.join('').length < 4) continue
    told.add(slot)
    beats.push({ ...beatAt(at, ''), title: actions.join('\n') })
  }
  return beats
}

/** The things still waiting on the person that the model's reply says no longer are: done, answered, or not needed now. */
export const parseCleared = (reply: string, job: Job): string[] => {
  const cleared = new Set<string>()
  for (const raw of reply.split('\n')) {
    const found = /^\s*[-*]?\s*clear\s*\|\s*\[?w?(\d+)\]?\s*$/i.exec(raw)
    const id = found ? job.open[Number(found[1]) - 1] : undefined
    if (id) cleared.add(id)
  }
  return [...cleared]
}

/**
 * What the model's reply says of the pictures the log marked, by picture: only where it had something to say.
 * One the log told nothing of keeps no caption, so the conversation itself can still be asked about it.
 */
export const parsePictures = (reply: string, job: Job): { id: string; text: string }[] => {
  const told = new Map<string, string>()
  for (const raw of reply.split('\n')) {
    const found = /^\s*[-*]?\s*pic\s*\|\s*\[?p?(\d+)\]?\s*\|\s*(.*?)\s*$/i.exec(raw)
    const id = found ? job.pics[Number(found[1]) - 1] : undefined
    const text = found ? clean(found[2]!) : ''
    if (id && !told.has(id) && text.length >= 4 && !/^[-–—]+$/.test(text)) told.set(id, clip(text, CAPTION_MAX))
  }
  return [...told].map(([id, text]) => ({ id, text }))
}

/** The web page of a repository on GitHub, from its remote as git has it; '' for any other. */
export const repoPage = (remote: string | null | undefined): string => {
  const found = /^(?:https?:\/\/(?:[^@/]+@)?github\.com\/|git@github\.com:|ssh:\/\/git@github\.com\/)([A-Za-z0-9_.-]+)\/([A-Za-z0-9_.-]+?)(?:\.git)?\/?$/.exec((remote ?? '').trim())
  return found ? `https://github.com/${found[1]}/${found[2]}` : ''
}

/**
 * Things waiting on the person that name pull requests by number, with the
 * link to each added when the session's repository is on GitHub: the number
 * and the repository are all a link is made of, so it is no guess.
 */
export const withPullLinks = (beats: Beat[], remote: string | null | undefined): Beat[] => {
  const page = repoPage(remote)
  if (!page) return beats
  return beats.map(beat => {
    if (beat.kind !== 'waiting') return beat
    const numbers: string[] = []
    for (const named of beat.title.matchAll(/\b(?:PRs?|pull requests?)\s*#?(\d+)((?:\s*(?:,|or|and|&)\s*#?\d+)*)/gi)) {
      for (const one of [named[1]!, ...[...named[2]!.matchAll(/\d+/g)].map(found => found[0])]) if (!numbers.includes(one)) numbers.push(one)
    }
    const had = beat.refs ?? []
    const links = numbers.map(number => `${page}/pull/${number}`).filter(link => !had.some(ref => ref.replace(/\/$/, '') === link))
    return links.length > 0 ? { ...beat, refs: [...links, ...had].slice(0, REFS_MOST + links.length) } : beat
  })
}

const sameWords = (a: string, b: string): boolean => a.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim() === b.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim()

/**
 * The trail with the updates in, the steps they tell of marked as told and relieved of what was kept only for
 * the telling. What the reply left waiting on the person is taken only from a log that ran to the latest (an
 * older stretch's is long since dealt with), and what it cleared stops waiting as of the log's last step.
 * What it said of the pictures becomes their captions.
 */
export const feedIn = (trail: Trail, job: Job, beats: Beat[], cleared: string[] = [], captions: { id: string; text: string }[] = []): Trail => {
  const covered = new Set(job.ids)
  const notes = new Map(captions.map(one => [one.id, one.text]))
  const known = new Set(trail.feed.map(beat => beat.id))
  const over = new Set(cleared)
  const overAt = job.slots.reduce((latest, slot) => Math.max(latest, slot.at), 0)
  // A thing already waiting that the reply tells of again, now with what it is done with, gains that.
  const gained = (beat: Beat): string[] | undefined =>
    beat.kind === 'waiting' && beat.over === undefined && !beat.refs?.length ? beats.find(told => told.kind === 'waiting' && told.refs?.length && (told.id === beat.id || sameWords(told.title, beat.title)))?.refs : undefined
  const had = trail.feed.map(beat => {
    const refs = gained(beat)
    const kept = refs ? { ...beat, refs } : beat
    return over.has(kept.id) && kept.over === undefined ? { ...kept, over: overAt } : kept
  })
  const stillOpen = had.filter(beat => beat.kind === 'waiting' && beat.over === undefined)
  const fresh = [...(job.local ?? []), ...beats].filter(beat => !known.has(beat.id) && (beat.kind !== 'waiting' || (job.isLatest && !stillOpen.some(other => sameWords(other.title, beat.title)))))
  const feed = [...had, ...fresh].sort((a, b) => a.turn - b.turn || a.at - b.at)
  return {
    ...trail,
    feed: feed.slice(-MAX_BEATS),
    items: trail.items.map(found => {
      const note = notes.get(found.id)
      const item = note !== undefined && found.shot && found.shot.note === undefined ? { ...found, shot: { ...found.shot, note, guess: true as const } } : found
      if (!covered.has(item.id)) return item
      // What was kept only for the telling is let go; a request keeps its words, which are the person's to read back.
      const { more, ...told } = item
      return { ...told, ...(item.kind === 'ask' && more ? { more } : {}), fed: true as const, ...(told.work ? { work: { ...told.work, notes: [] } } : {}) }
    }),
  }
}

/**
 * A trail read back from its transcript, with what only the mod knew kept:
 * the updates already written for it (nothing is told twice), the captions
 * of its pictures and the answers given to its questions. Asked to tell the
 * latest again, it leaves the newest turns that fit one log untold: their
 * updates stand, and the model reads them once more for what they left
 * waiting on the person.
 */
export const adopt = (built: Trail, had: Trail, isRetelling = false): Trail => {
  const again = new Set<number>()
  if (isRetelling) {
    let room = RETOLD_MAX
    for (const turn of [...new Set(built.items.map(item => item.turn))].sort((a, b) => b - a)) {
      if (built.isOpen && turn === built.turn) continue
      room -= built.items.filter(item => item.turn === turn).reduce((sum, item) => sum + (item.more ?? item.line).length + 60, 0)
      if (room < 0 && again.size > 0) break
      again.add(turn)
    }
  }
  const told = new Set(had.items.filter(item => item.fed).map(item => item.id))
  for (const item of built.items) if (again.has(item.turn)) told.delete(item.id)
  const notes = new Map(had.items.flatMap(item => (item.shot?.note === undefined ? [] : [[item.id, { note: item.shot.note, ...(item.shot.guess ? { guess: true as const } : {}) }] as const])))
  const turnOf = new Map(built.items.map(item => [item.id, item.turn]))
  const asked = new Map(had.questions.map(question => [question.id, question]))
  const { sought: _, ...rest } = built
  return {
    ...rest,
    // What was told before the mod looked for what waits on the person stays so marked until its latest is told again.
    ...(isRetelling || had.sought ? { sought: true as const } : {}),
    // An update keeps to the step it was tied to, wherever that step's turn now counts from.
    feed: had.feed.map(beat => ({ ...beat, turn: turnOf.get(beat.ref) ?? beat.turn })),
    questions: [...built.questions.map(question => asked.get(question.id) ?? question), ...had.questions.filter(question => !built.questions.some(other => other.id === question.id))].sort((a, b) => a.at - b.at),
    items: built.items.map(found => {
      const note = notes.get(found.id)
      const item = note !== undefined && found.shot ? { ...found, shot: { ...found.shot, ...note } } : found
      if (!told.has(item.id)) return item
      const { more, ...kept } = item
      return { ...kept, ...(item.kind === 'ask' && more ? { more } : {}), fed: true as const }
    }),
  }
}

files.hooks/caption.ts:
// What each picture of the feed shows and what it was about, asked of the conversation itself: the model that
// writes the updates reads a log and sees no picture, while the conversation holds them and what was said of
// them. Pure: the hooks module puts the question; this words it and reads the answer.

import type { Item, Trail } from '../types'
import { clean, clip } from './trail.ts'

/** Pictures to ask about. */
export type CaptionJob = {
  /** The pictures, by the number each has in the question. */
  shots: Item[]
  prompt: string
}

/** Pictures asked about at once, newest first: more would be a long answer and old ones may have left the conversation. */
const MOST = 10
const CAPTION_MAX = 320
const SAID_MAX = 110

const INTRO = [
  'This message is not from the person. It is the Trail side pane, which shows them an activity feed of this conversation, asking you for captions for the pictures and other outputs in that feed. Do not go on with the work and do not use any tool: only answer this.',
  '',
  'For each picture listed below, write a caption of one or two plain sentences, at most thirty-five words, that says what the picture shows and what it was about:',
  '- for a picture the person pasted: what they were showing you and what they were telling you with it;',
  '- for a picture you opened or were given by a tool: why you looked at it and what you saw in it;',
  '- for a picture you sent them: what it shows and why you sent it.',
  'Say what you made of it, concretely, so that someone who has not seen the conversation understands the picture. Write to the person as "you". No filler.',
  'If you cannot find a picture in this conversation, write a single dash for it.',
  '',
  'The pictures, oldest first:',
]

const OUTRO = ['', 'Reply with one line per picture and nothing else:', 'N|caption']

/** How the question names a picture, so the conversation can tell which is meant. */
const described = (shot: Item, trail: Trail, time: (at: number) => string): string => {
  const when = shot.at > 0 ? ` at ${time(shot.at)}` : ''
  const ask = trail.items.find(item => item.kind === 'ask' && item.id === shot.anchor)
  if (ask) {
    const fellows = trail.items.filter(item => item.kind === 'shot' && item.anchor === shot.anchor)
    const place = fellows.length > 1 ? ` (picture ${fellows.indexOf(shot) + 1} of ${fellows.length} in that message)` : ''
    return `a picture the person pasted${when}, with their message beginning "${clip(ask.line, SAID_MAX)}"${place}`
  }
  const type = shot.shot?.type ?? 'image'
  if (type === 'link') return `the page you published${when} (${shot.line}): say what it is and what it is for`
  if (type === 'video') return `the video ${shot.line.replace(/^Sent you /, '')}, which ${shot.line.startsWith('Sent you ') ? 'you sent the person' : 'a command you ran made'}${when}: you cannot see it here, so say what it is of and what it was made for`
  if (type === 'file') return `the file ${shot.line.replace(/^Sent you /, '')}, which you sent the person${when}: say what it is and what it is for`
  if (shot.line.startsWith('Sent you ')) return `the picture ${shot.line.slice('Sent you '.length)}, which you sent the person${when}`
  if (shot.line.startsWith('Picture from ')) return `a picture a tool returned to you${when} (${shot.line.slice('Picture from '.length)})`
  return `the picture ${shot.line}, which you opened${when}`
}

/**
 * The pictures still without a caption of the conversation's own (none at
 * all, or one only made out from the words around it), as a question for it:
 * only those since the context was last compacted, which are the ones it
 * still holds. Null when there are none.
 */
export const captionJob = (trail: Trail, time: (at: number) => string): CaptionJob | null => {
  const since = trail.items.map(item => item.kind).lastIndexOf('compact')
  const shots = trail.items.filter((item, index) => index > since && item.kind === 'shot' && item.shot !== undefined && (item.shot.note === undefined || item.shot.guess === true)).slice(-MOST)
  if (shots.length === 0) return null
  const lines = shots.map((shot, index) => `${index + 1}. ${described(shot, trail, time)}`)
  return { shots, prompt: [...INTRO, ...lines, ...OUTRO].join('\n') }
}

/**
 * The answer as captions, by picture. One the conversation could not find,
 * or gave no line for, gets an empty caption: it has been asked about, and
 * is not asked about again.
 */
export const parseCaptions = (reply: string, job: CaptionJob): { id: string; text: string }[] => {
  const told = new Map<number, string>()
  for (const raw of reply.split('\n')) {
    const found = /^\s*[-*]?\s*\[?(\d+)\]?\s*[|.:)]\s*(.*?)\s*$/.exec(raw)
    if (!found) continue
    const index = Number(found[1]) - 1
    if (index < 0 || index >= job.shots.length || told.has(index)) continue
    const text = clean(found[2]!)
    told.set(index, /^[-–—]*$/.test(text) ? '' : clip(text, CAPTION_MAX))
  }
  // An answer with no line in the form asked for is no answer: the pictures are asked about another time.
  if (told.size === 0) return []
  return job.shots.map((shot, index) => ({ id: shot.id, text: told.get(index) ?? '' }))
}

files.hooks/jump.ts:
// Which transcript row a line jumps to, and what to try when that row will not scroll.
// Pure: the scroll itself is handed in, so the order of tries can be tested without a transcript.

/** The engine's word for a scroll nothing the person did asked for: no other row will fare better. */
const NOT_ASKED = 'not person-initiated'

/**
 * The ids a line's row may answer to, likeliest first. A message's row is
 * drawn under its own id. A tool call's row is too, unless the transcript
 * folded it into a run of calls ("Read 3 files"): then the run's id is the
 * one that scrolls. After those, the same for the tool call beside the row.
 */
export const candidates = (target: { anchor: string; alt?: string }, groupsByCall: ReadonlyMap<string, string>): string[] => {
  const all = [groupsByCall.get(target.anchor), target.anchor, target.alt ? groupsByCall.get(target.alt) : undefined, target.alt]
  return all.filter((id, index): id is string => typeof id === 'string' && id !== '' && all.indexOf(id) === index)
}

export type Reached = {
  /** Why the transcript did not move; '' when it did. */
  why: string
  /** Each id tried and what came of it, for whoever is working on the mod. */
  tried: string[]
}

/** Tries each id in turn until one scrolls; `scroll` resolves why not, or undefined when it moved. */
export const reach = async (ids: readonly string[], scroll: (id: string) => Promise<string | undefined>): Promise<Reached> => {
  const tried: string[] = []
  let why = 'no row is known for this line'
  for (const id of ids) {
    const deny = await scroll(id)
    tried.push(`${id}=${deny ?? 'ok'}`)
    why = deny ?? ''
    if (why === '' || why === NOT_ASKED) break
  }
  return { why, tried }
}

files.hooks/prune.ts:
// What of the mod's kept data is past keeping. Pure: the hooks module lists the folders and removes what this names.
//
// Each session has a folder with its trail in it, which is small. The mod no longer keeps pictures at all (it tells
// of them in words and opens the file itself), so the `shots` folders that older versions filled are only there to
// be cleared: a session's goes once it has been idle a day, and a whole-size copy a day after it was made. The
// folder itself goes when the transcript would, after the days Claude Code keeps one.

/** Days a session may be idle before the pictures an older version kept for it are let go. */
export const PICTURES_DAYS = 1
/** Days a session's folder is kept when the person's settings do not say how long transcripts are. */
export const KEEP_DAYS = 30
const DAY_MS = 86_400_000
/** A session's folder is named by its id; nothing else in the mod's folder is ever removed. */
const SESSION = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/
/** A whole-size copy of a picture, as the mod names one beside its small copy. */
const WHOLE_COPY = /^[A-Za-z0-9_-]+\.full\.[A-Za-z0-9]+$/

export const isSession = (name: string): boolean => SESSION.test(name)

/** One folder in the mod's own: its name, when its trail was last written (0 when that is not known), whether it has pictures. */
export type Kept = { name: string; touchedAt: number; hasShots: boolean }

/** The days a session's folder is kept: as long as Claude Code keeps its transcript (`cleanupPeriodDays`), a month when that is not set. */
export const keepDays = (setting: unknown): number => (typeof setting === 'number' && Number.isFinite(setting) && setting >= 1 ? Math.floor(setting) : KEEP_DAYS)

/**
 * The folders to remove whole, and those to remove only the pictures of.
 * The session asking is never among them, nor is a folder whose age is not
 * known or whose name is not a session's.
 */
export const prunable = (kept: readonly Kept[], now: number, own: string, days: number): { folders: string[]; pictures: string[] } => {
  const folders: string[] = []
  const pictures: string[] = []
  for (const one of kept) {
    if (!SESSION.test(one.name) || one.name === own || one.touchedAt <= 0) continue
    const idle = (now - one.touchedAt) / DAY_MS
    if (idle >= days) folders.push(one.name)
    else if (idle >= Math.min(PICTURES_DAYS, days) && one.hasShots) pictures.push(one.name)
  }
  return { folders, pictures }
}

/**
 * The whole-size copies in one session's pictures that are past keeping: made
 * a day ago or more. Versions before 0.4 copied every picture whole, which
 * was most of what the mod kept; none is made any more.
 */
export const staleCopies = (files: readonly { name: string; kind: string; mtimeMs: number }[], now: number): string[] =>
  files.filter(file => file.kind === 'file' && WHOLE_COPY.test(file.name) && file.mtimeMs > 0 && now - file.mtimeMs >= PICTURES_DAYS * DAY_MS).map(file => file.name)

/** A size in bytes as a person reads it: "143 MB". */
export const sized = (kilobytes: number): string => (kilobytes >= 1024 * 1024 ? (kilobytes / 1024 / 1024).toFixed(1) + ' GB' : kilobytes >= 1024 ? Math.round(kilobytes / 1024) + ' MB' : Math.max(0, Math.round(kilobytes)) + ' KB')

files.hooks/trail.ts:
// The trail's steps: conversation events in, a list of what happened out.
// Pure (no `$`, no Node, no DOM), so the hooks, the tests and the rebuild tool share it.

import type { Beat, Item, ItemKind, OutputType, Question, Shot, Source, Trail, Work } from '../types'

export type TrailEvent =
  | { t: 'prompt'; id: string; at: number; text: string; isCommand?: boolean }
  | { t: 'say'; id: string; at: number; text: string }
  | { t: 'tool'; id: string; at: number; tool: string; note: string; file?: string }
  | { t: 'fail'; id: string; at: number }
  | { t: 'shot'; id: string; at: number; anchor: string; file: string; w: number; h: number; label: string; full?: string; stamp?: number; type?: OutputType; from?: Source; note?: string }
  | { t: 'recap'; id: string; at: number; text: string }
  | { t: 'compact'; id: string; at: number }
  | { t: 'question'; id: string; at: number; text: string; options: string[]; shot?: Shot }
  | { t: 'answer'; id: string; at: number; text: string }
  | { t: 'caption'; id: string; at: number; text: string }
  | { t: 'opened'; id: string; at: number }
  | { t: 'end'; at: number; aborted?: boolean }

export const MAX_ITEMS = 400
export const MAX_BEATS = 300
const MAX_QUESTIONS = 40
const QUESTION_MAX = 400
const OPTIONS_MOST = 4
const OPTION_MAX = 28
/** What a question the conversation went on past is taken to have been answered with. */
export const ANSWERED_THERE = 'answered in the conversation'
const FILES_KEPT = 3
const EXTRA_KEPT = 24
const NOTES_KEPT = 8
const RECENT_KEPT = 60
const LINE_MAX = 200
const RECAP_MAX = 600
const NOTE_MAX = 320
/** How much of what was said is kept for a highlight to be written from: all of an answer, the start of a step. */
const ANSWER_MAX = 1600
/** Of an answer longer than that, how much is its end: where it says how things stand and what waits on the person. */
const ANSWER_END = 600
const STEP_MAX = 320
const SENTENCE_MIN = 32
/** A line this long before a list or a break stands on its own. */
const LEAD_MIN = 20
const CARRIED_ON = 'Carried on without a new prompt'
const TASK = 'Background task: '

/** How an answer given in the pane reads when it reaches the conversation, and how it is known again in a transcript. */
export const paneAnswer = (question: string, answer: string): string => `About your question in the Trail pane ("${question}"): ${answer}`
const PANE_ANSWER = /^About your question in the Trail pane \("[\s\S]*?"\): ([\s\S]+)$/

export const emptyTrail = (): Trail => ({ items: [], feed: [], questions: [], turn: 0, isOpen: false, isFresh: false, lastTool: '', lastAt: 0, recent: [], sought: true })

const emptyWork = (): Work => ({ cmds: 0, reads: 0, edits: 0, agents: 0, other: 0, fails: 0, files: [], moreFiles: 0, extra: [], now: '', notes: [] })

const READS = new Set(['Read', 'Grep', 'Glob', 'WebFetch', 'WebSearch', 'ToolSearch'])
const EDITS = new Set(['Write', 'Edit', 'NotebookEdit'])
const AGENTS = new Set(['Agent', 'Task', 'Workflow'])

/** A short name for a long string, the same wherever it is worked out: what a file made from a path is called by. */
export const tag = (text: string): string => {
  let hash = 5381
  for (let i = 0; i < text.length; i++) hash = ((hash << 5) + hash + text.charCodeAt(i)) | 0
  return (hash >>> 0).toString(36)
}

const MOVING = /\.(mp4|mov|m4v|webm|mkv|gif)$/i
const STILL = /\.(png|jpe?g|webp|heic|tiff?|bmp)$/i

/** A file last written this long before a session's first event was there before it: looked at, not made. */
const EARLIER_MS = 60_000

/** Whether a file Claude opened is from before the session, given when it was last written and when the session began. */
export const isEarlier = (writtenAt: number, beganAt: number): boolean => beganAt > 0 && writtenAt > 0 && writtenAt < beganAt - EARLIER_MS

/**
 * Whether a picture of the trail is Claude's own output: something the
 * session made, sent or published, and not one the person pasted or a file
 * from before the session that Claude only looked at.
 */
export const isOwnOutput = (item: Item, trail: Trail): boolean =>
  item.kind === 'shot' && item.shot?.from === undefined && !trail.items.some(other => other.kind === 'ask' && other.id === item.anchor)

/** The things the work left for the person to do that they have not done yet, oldest first. */
export const waitsOf = (trail: Trail): Beat[] => trail.feed.filter(beat => beat.kind === 'waiting' && beat.over === undefined)

/** How many things wait on the person: questions put to them in the pane, and what the work left for them to do. */
export const waitingCount = (trail: Trail): number => trail.questions.filter(question => question.answer === undefined).length + waitsOf(trail).length

/** How a file Claude handed the person is named in the trail. */
export const SENT = 'Sent you '

/** What kind of output a file is, by its name. */
export const outputType = (path: string): OutputType => (MOVING.test(path) ? 'video' : STILL.test(path) ? 'image' : 'file')

/**
 * The video files a command names, in what it ran and what it printed: what
 * rendering or recording leaves behind and nobody opens with a tool. Paths
 * as written, a few at most; whether each is a file just made is the caller's
 * to find out.
 */
export const videosNamed = (text: string): string[] => {
  const found = new Set<string>()
  for (const match of text.matchAll(/(?:^|[\s'"=(:])((?:~\/|\.{0,2}\/)?[\w@%+,.\-\/]+\.(?:mp4|mov|m4v|webm|mkv|gif))(?=$|[\s'"),;:])/gim)) {
    found.add(match[1]!)
    if (found.size >= 5) break
  }
  return [...found]
}

/** The address a page was published at, in what the tool that published it answered. */
export const publishedAt = (text: string): string | undefined => /\bPublished\b[^\n]*?\bat (https:\/\/[^\s)]+)/.exec(text)?.[1]

export const basename = (path: string): string => {
  const cut = path.replace(/\/+$/, '')
  return cut.slice(cut.lastIndexOf('/') + 1)
}

const span = (from: number, to: number): string => String.fromCharCode(from) + '-' + String.fromCharCode(to)
/** Control characters and the marks that turn text around or hide in it: one of them in a tree refuses the whole pane. */
const UNSEEN = new RegExp('[' + span(0, 0x1f) + span(0x7f, 0x9f) + span(0x200b, 0x200f) + span(0x2028, 0x202e) + String.fromCharCode(0xfeff) + ']', 'g')

/** One line of plain characters. */
export const clean = (text: string): string => text.replace(UNSEEN, ' ').replace(/\s+/g, ' ').trim()

/** Cut by characters, never through one, at a word where there is one near. */
export const clip = (text: string, max: number): string => {
  const chars = Array.from(text)
  if (chars.length <= max) return text
  const cut = chars.slice(0, max - 1).join('')
  const space = cut.lastIndexOf(' ')
  return (space > cut.length * 0.6 ? cut.slice(0, space) : cut).replace(/[\s,;:]+$/, '') + '…'
}

const plain = (text: string): string =>
  clean(
    text
      .replace(/```[\s\S]*?(```|$)/g, ' ')
      .replace(/^\s{0,3}(#{1,6}|[-*+]|\d+\.)\s+/gm, '')
      .replace(/\*\*([^*]+)\*\*/g, '$1')
      .replace(/`([^`]+)`/g, '$1')
      .replace(/\[([^\]]+)\]\((?:[^)]+)\)/g, '$1'),
  )

/** Characters kept of one block of code in what is put to the model. */
const CODE_KEPT = 300

/**
 * What was said, flattened for the model that tells of it: as `plain`, but
 * with what the person may have to act on kept. The commands in its code
 * blocks stay, each on one line between backticks, and a link keeps where it
 * leads. Without these the model cannot say what to run or what to open.
 */
const telling = (text: string): string =>
  clean(
    text
      .replace(/```(?:[A-Za-z0-9_+-]*\n)?([\s\S]*?)(?:```|$)/g, (_, code: string) => (code.trim() ? ' `' + clip(code.replace(/\s+/g, ' ').trim(), CODE_KEPT) + '` ' : ' '))
      .replace(/^\s{0,3}(#{1,6}|[-*+]|\d+\.)\s+/gm, '')
      .replace(/\*\*([^*]+)\*\*/g, '$1')
      .replace(/\[([^\]]+)\]\(([^)\s]+)\)/g, (_, label: string, to: string) => (/^https?:/.test(to) && to !== label ? `${label} (${to})` : label)),
  )

/** What is kept of an answer: all of it, or of a long one its start and its end, the middle left out. */
const headAndEnd = (flat: string): string => {
  const chars = Array.from(flat)
  if (chars.length <= ANSWER_MAX) return flat
  const end = chars.slice(-ANSWER_END).join('')
  return clip(flat, ANSWER_MAX - ANSWER_END) + ' ' + end.slice(end.indexOf(' ') + 1)
}

/** Where the first sentence of a plain line ends; a very short one takes the next along. */
const sentenceEnd = (flat: string): number => {
  const stop = /[.!?:](?=\s+[A-Z"'`(\[]|$)/g
  for (let match = stop.exec(flat); match; match = stop.exec(flat)) {
    const isLast = match.index + 1 >= flat.length
    if (!isLast && (match[0] === ':' || match.index + 1 < SENTENCE_MIN)) continue
    return match.index + 1
  }
  return flat.length
}

/** A line that leads into a list or a new paragraph says its piece alone: the first item is not the rest of its sentence. */
const lead = (text: string): string => {
  const cut = /\n(?=\s*\n|\s{0,3}(?:[-*+]|\d+\.)\s)/.exec(text)
  return cut && plain(text.slice(0, cut.index)).length >= LEAD_MIN ? text.slice(0, cut.index) : text
}

/** The first sentence of what the model said, as one plain line. */
export const firstSentence = (text: string): string => {
  const flat = plain(lead(text))
  return clip(flat.slice(0, sentenceEnd(flat)), LINE_MAX)
}

const TAGGED = /<(system-reminder|local-command-stdout|local-command-stderr|local-command-caveat|task-notification|command-message|skill-format|bash-stdout|bash-stderr)>[\s\S]*?<\/\1>/g
const INTERRUPTED = /^\s*\[Request interrupted by user/

/** The person's prompt as one plain line; empty for rows that are not a prompt at all. */
export const promptLine = (text: string, max = LINE_MAX): string => {
  const command = /<command-name>\s*(\/?[^<\s]+)\s*<\/command-name>/.exec(text)
  if (command) {
    const args = /<command-args>([\s\S]*?)<\/command-args>/.exec(text)
    const name = command[1]!.startsWith('/') ? command[1]! : '/' + command[1]!
    return clip(clean(name + ' ' + (args?.[1] ?? '')), max)
  }
  const task = /<task-notification>([\s\S]*?)(?:<\/task-notification>|$)/.exec(text)
  const summary = task && /<summary>([\s\S]*?)<\/summary>/.exec(task[1]!)
  if (summary) {
    // How the task came out is what matters about it: said first, where no clip takes it.
    const said = clean(summary[1]!)
    const status = clean(/<status>([\s\S]*?)<\/status>/.exec(task![1]!)?.[1] ?? '')
    return clip((status && !said.toLowerCase().includes(status.toLowerCase()) ? `Background task ${status}: ` : TASK) + said, max)
  }
  // The engine's own mark for a turn the person stopped is no prompt of theirs.
  if (INTERRUPTED.test(text)) return ''
  const shell = /<bash-input>([\s\S]*?)<\/bash-input>/.exec(text)
  if (shell) return clip(clean('! ' + shell[1]!), max)
  const said = text
    .replace(TAGGED, ' ')
    .replace(/<\/?pasted_content[^>]*>/g, ' ')
    .replace(/\[Image(?: #\d+|: source: [^\]]*)\]/g, ' ')
  return clip(clean(said), max)
}

/** One short phrase for a tool call, from its own arguments. */
export const toolNote = (tool: string, input: Record<string, unknown>): string => {
  const text = (key: string): string => (typeof input[key] === 'string' ? (input[key] as string) : '')
  const note =
    text('description') ||
    (text('file_path') && basename(text('file_path'))) ||
    text('skill') ||
    text('query') ||
    text('url') ||
    text('pattern') ||
    text('command') ||
    text('name')
  const short = tool.startsWith('mcp__') ? tool.split('__').slice(2).join(' ') || tool : tool
  return clip(clean(note || short), 80)
}

export const workCount = (work: Work): number => work.cmds + work.reads + work.edits + work.agents + work.other

const tally = (work: Work, tool: string, note: string, file?: string): Work => {
  const next = { ...work, now: note }
  // A call that says what it is for is what a highlight is written from; a bare file name says little.
  const isTelling = note !== '' && (tool === 'Bash' || AGENTS.has(tool) || tool.startsWith('mcp__') || tool === 'Skill' || tool === 'WebSearch')
  if (isTelling && next.notes.length < NOTES_KEPT && !next.notes.includes(note)) next.notes = [...next.notes, note]
  if (tool === 'Bash') next.cmds++
  else if (READS.has(tool)) next.reads++
  else if (EDITS.has(tool)) {
    next.edits++
    const name = file ? clean(basename(file)) : ''
    if (name && !next.files.includes(name) && !next.extra.includes(name)) {
      if (next.files.length < FILES_KEPT) next.files = [...next.files, name]
      else {
        next.moreFiles++
        if (next.extra.length < EXTRA_KEPT) next.extra = [...next.extra, name]
      }
    }
  } else if (AGENTS.has(tool)) next.agents++
  else next.other++
  return next
}

const merge = (into: Work, from: Work): Work => {
  const files = [...into.files]
  const extra = [...into.extra]
  let moreFiles = into.moreFiles
  for (const name of [...from.files, ...from.extra]) {
    if (files.includes(name) || extra.includes(name)) continue
    if (files.length < FILES_KEPT) files.push(name)
    else {
      moreFiles++
      if (extra.length < EXTRA_KEPT) extra.push(name)
    }
  }
  // Names past what either kept are counted, though not known.
  moreFiles += Math.max(0, from.moreFiles - from.extra.length)
  return {
    cmds: into.cmds + from.cmds,
    reads: into.reads + from.reads,
    edits: into.edits + from.edits,
    agents: into.agents + from.agents,
    other: into.other + from.other,
    fails: into.fails + from.fails,
    files,
    moreFiles,
    extra,
    now: from.now || into.now,
    notes: [...into.notes, ...from.notes.filter(note => !into.notes.includes(note))].slice(0, NOTES_KEPT),
  }
}

export const change = (items: Item[], index: number, to: (item: Item) => Item): Item[] => {
  const next = items.slice()
  next[index] = to(next[index]!)
  return next
}

const withKind = (items: Item[], index: number, kind: ItemKind): Item[] => change(items, index, item => ({ ...item, kind }))

/** The line of the turn that tool calls count under: its newest ask, step or result. */
const bearerOf = (items: Item[], turn: number, before = items.length): number => {
  for (let i = before - 1; i >= 0; i--) {
    const item = items[i]!
    if (item.kind === 'recap' || item.kind === 'compact' || item.kind === 'shot') continue
    return item.turn === turn ? i : -1
  }
  return -1
}

/**
 * Keeps the list bounded. Steps go first, their work kept under the line
 * before them: those of older turns, then the oldest of the running turn. A
 * turn never loses its ask, result or pictures that way; only when nothing
 * but those is left do whole turns go, oldest first.
 */
const thin = (items: Item[]): Item[] => {
  if (items.length <= MAX_ITEMS) return items
  const out = items.slice()
  let over = out.length - MAX_ITEMS
  const newest = out[out.length - 1]!.turn
  for (const ofNewest of [false, true]) {
    for (let i = 0; i < out.length - 1 && over > 0; i++) {
      const item = out[i]!
      if (item.kind !== 'step' || (item.turn === newest) !== ofNewest) continue
      const bearer = bearerOf(out, item.turn, i)
      if (bearer < 0) continue
      if (item.work) out[bearer] = { ...out[bearer]!, work: merge(out[bearer]!.work ?? emptyWork(), item.work) }
      out.splice(i, 1)
      i--
      over--
    }
  }
  if (over <= 0) return out
  let cut = over
  while (cut < out.length - 1 && out[cut]!.turn === out[cut - 1]!.turn) cut++
  return out.slice(cut)
}

const has = (trail: Trail, id: string): boolean => trail.items.some(item => item.id === id)

/** A turn to put work under: the one running, the newest ask's if it has not ended, else one nobody asked for. */
const reopen = (trail: Trail, id: string, at: number): Trail => {
  if (trail.isOpen) return trail
  if (trail.isFresh) return { ...trail, isOpen: true }
  const turn = trail.turn + 1
  const ask: Item = { id: id + ':turn', anchor: id, kind: 'ask', at, turn, line: CARRIED_ON }
  return { ...trail, items: [...trail.items, ask], turn, isOpen: true, isFresh: true }
}

const seenOnce = (trail: Trail, key: string): Trail | null =>
  trail.recent.includes(key) ? null : { ...trail, recent: [...trail.recent, key].slice(-RECENT_KEPT) }

/** Folds one thing that happened into the trail. */
export const add = (trail: Trail, event: TrailEvent): Trail => {
  const next = fold(trail, event)
  // A caption is written after the fact: it is no sign of when the work last moved.
  return event.t !== 'caption' && event.at > next.lastAt ? { ...next, lastAt: event.at } : next
}

const fold = (trail: Trail, event: TrailEvent): Trail => {
  switch (event.t) {
    case 'prompt': {
      if (has(trail, event.id)) return trail
      const line = promptLine(event.text)
      if (!line) return trail
      // A command typed while a turn runs is beside the point of that turn: it neither ends it nor heads the work after.
      if (event.isCommand && trail.isOpen) return trail
      // A turn never seen to end stopped when it last did something, not when the person next spoke, and with no result.
      const closed = trail.isOpen ? fold(trail, { t: 'end', at: trail.lastAt || event.at, aborted: true }) : trail
      const turn = closed.turn + 1
      const ask: Item = { id: event.id, anchor: event.id, kind: 'ask', at: event.at, turn, line }
      const whole = promptLine(event.text, ANSWER_MAX)
      if (whole.length > line.length) ask.more = whole
      // Whatever the person says next is taken as their answer to what was waiting on them: said in the pane, it
      // names the question; said in the conversation, the conversation has it.
      const isTheirs = event.isCommand !== true && !/^Background task\b/.test(line)
      const given = PANE_ANSWER.exec(whole)?.[1]
      const questions = isTheirs
        ? closed.questions.map(question => (question.answer === undefined ? { ...question, answer: clip(given ?? ANSWERED_THERE, QUESTION_MAX), answeredAt: event.at } : question))
        : closed.questions
      return { ...closed, items: thin([...closed.items, ask]), questions, turn, isOpen: event.isCommand !== true, isFresh: true }
    }
    case 'say': {
      if (has(trail, event.id)) return trail
      const flat = plain(event.text)
      const line = clip(flat.slice(0, sentenceEnd(flat)), LINE_MAX)
      if (!line) return trail
      const base = reopen(trail, event.id, event.at)
      // What was said before this turned out not to be the turn's answer: its start is enough to keep.
      const before = bearerOf(base.items, base.turn)
      const items =
        before >= 0 && base.items[before]!.kind === 'step' && (base.items[before]!.more?.length ?? 0) > STEP_MAX
          ? change(base.items, before, item => ({ ...item, more: clip(item.more ?? '', STEP_MAX) }))
          : base.items
      const step: Item = { id: event.id, anchor: event.id, kind: 'step', at: event.at, turn: base.turn, line }
      // What is kept for the telling has the commands and the links of what was said, which the line shown does not.
      const told = telling(event.text)
      if (flat.length > line.length || told !== flat) step.more = headAndEnd(told)
      if (base.lastTool) step.alt = base.lastTool
      return { ...base, items: thin([...items, step]) }
    }
    case 'tool': {
      const counted = seenOnce(trail, event.id)
      if (!counted) return trail
      const base = { ...reopen(counted, event.id, event.at), lastTool: event.id }
      const bearer = bearerOf(base.items, base.turn)
      if (bearer < 0) return base
      const items = base.items[bearer]!.kind === 'done' ? withKind(base.items, bearer, 'step') : base.items
      return {
        ...base,
        items: change(items, bearer, item => ({
          ...item,
          // The row a line stands for may not scroll; the first call made under it is beside it and does.
          alt: item.work && workCount(item.work) > 0 ? item.alt : event.id,
          work: tally(item.work ?? emptyWork(), event.tool, event.note, event.file),
        })),
      }
    }
    case 'fail': {
      const counted = seenOnce(trail, 'fail:' + event.id)
      if (!counted) return trail
      const bearer = bearerOf(counted.items, counted.turn)
      if (bearer < 0) return counted
      return { ...counted, items: change(counted.items, bearer, item => ({ ...item, work: { ...(item.work ?? emptyWork()), fails: (item.work?.fails ?? 0) + 1 } })) }
    }
    case 'shot': {
      const id = event.id + ':shot'
      if (has(trail, id)) return trail
      const base = reopen(trail, event.id, event.at)
      const shot: Item = {
        id,
        anchor: event.anchor,
        kind: 'shot',
        at: event.at,
        turn: base.turn,
        line: clip(clean(event.label), LINE_MAX),
        shot: { file: event.file, w: event.w, h: event.h },
      }
      if (event.full) shot.shot!.full = event.full
      if (event.stamp !== undefined) shot.shot!.stamp = event.stamp
      if (event.type && event.type !== 'image') shot.shot!.type = event.type
      if (event.from) shot.shot!.from = event.from
      // What Claude said of a file as it handed it over is its caption from the start.
      if (event.note && clean(event.note)) shot.shot!.note = clip(clean(event.note), NOTE_MAX)
      return { ...base, items: thin([...base.items, shot]) }
    }
    case 'recap': {
      const line = clip(plain(event.text), RECAP_MAX)
      if (!line || has(trail, event.id)) return trail
      // Only where things stand now is worth its rows: a newer recap takes the older one's place.
      const recap: Item = { id: event.id, anchor: event.id, kind: 'recap', at: event.at, turn: trail.turn, line }
      return { ...trail, items: thin([...trail.items.filter(item => item.kind !== 'recap'), recap]) }
    }
    case 'compact': {
      if (has(trail, event.id) || trail.items[trail.items.length - 1]?.kind === 'compact') return trail
      const at: Item = { id: event.id, anchor: event.id, kind: 'compact', at: event.at, turn: trail.turn, line: 'Context was compacted here' }
      if (trail.lastTool) at.alt = trail.lastTool
      return { ...trail, items: thin([...trail.items, at]) }
    }
    case 'question': {
      const text = clip(clean(event.text), QUESTION_MAX)
      if (!text || trail.questions.some(question => question.id === event.id)) return trail
      const options = event.options.map(option => clip(clean(option), OPTION_MAX)).filter(Boolean).slice(0, OPTIONS_MOST)
      const question: Question = { id: event.id, at: event.at, text, options }
      if (event.shot) question.shot = event.shot
      return { ...trail, questions: [...trail.questions, question].slice(-MAX_QUESTIONS) }
    }
    case 'answer': {
      const text = clip(clean(event.text), QUESTION_MAX)
      const index = trail.questions.findIndex(question => question.id === event.id && question.answer === undefined)
      if (index < 0 || !text) return trail
      const questions = trail.questions.slice()
      questions[index] = { ...questions[index]!, answer: text, answeredAt: event.at }
      return { ...trail, questions }
    }
    case 'opened': {
      // `id` is the output's own line: the person has opened it, so it reads as read from now on.
      const index = trail.items.findIndex(item => item.id === event.id && item.shot !== undefined)
      if (index < 0) return trail
      return { ...trail, items: change(trail.items, index, item => ({ ...item, shot: { ...item.shot!, opened: event.at } })) }
    }
    case 'caption': {
      // `id` is the picture's own line; an empty caption still says the picture was asked about.
      const index = trail.items.findIndex(item => item.id === event.id && item.shot !== undefined)
      if (index < 0) return trail
      const { guess: _, ...seen } = trail.items[index]!.shot!
      if (seen.note === event.text && trail.items[index]!.shot!.guess === undefined) return trail
      // The conversation saw the picture: what it says replaces what was only made out from the words around it.
      return { ...trail, items: change(trail.items, index, item => ({ ...item, shot: { ...seen, note: event.text || seen.note || '' } })) }
    }
    case 'end': {
      if (!trail.isOpen) return trail.isFresh ? { ...trail, isFresh: false } : trail
      let items = trail.items
      const last = bearerOf(items, trail.turn)
      // What the model said last, with nothing done after it, is how the turn came out, unless it was cut short.
      if (!event.aborted && last >= 0 && items[last]!.kind === 'step' && workCount(items[last]!.work ?? emptyWork()) === 0) items = withKind(items, last, 'done')
      const ask = items.findIndex(item => item.turn === trail.turn && item.kind === 'ask')
      if (ask >= 0) items = change(items, ask, item => ({ ...item, ms: Math.max(0, event.at - item.at) }))
      return { ...trail, items, isOpen: false, isFresh: false }
    }
  }
}

const isQuestion = (question: unknown): question is Question =>
  typeof question === 'object' && question !== null && typeof (question as Question).id === 'string' && typeof (question as Question).text === 'string' && Array.isArray((question as Question).options)

const isBeat = (beat: unknown): beat is Beat =>
  typeof beat === 'object' && beat !== null && typeof (beat as Beat).id === 'string' && typeof (beat as Beat).title === 'string' && typeof (beat as Beat).anchor === 'string'

/** A trail read back from a file or the state, with anything missing made whole. */
export const mended = (value: unknown): Trail | null => {
  if (typeof value !== 'object' || value === null) return null
  const from = value as Partial<Trail>
  if (!Array.isArray(from.items)) return null
  const items = from.items
    .filter((item): item is Item => typeof item === 'object' && item !== null && typeof item.id === 'string' && typeof item.line === 'string' && typeof item.kind === 'string')
    .map(item => (item.work && (!Array.isArray(item.work.notes) || !Array.isArray(item.work.extra)) ? { ...item, work: { ...emptyWork(), ...item.work, notes: item.work.notes ?? [], extra: item.work.extra ?? [] } } : item))
  return {
    items,
    feed: Array.isArray(from.feed) ? from.feed.filter(isBeat) : [],
    questions: Array.isArray(from.questions) ? from.questions.filter(isQuestion) : [],
    turn: typeof from.turn === 'number' ? from.turn : 0,
    isOpen: from.isOpen === true,
    isFresh: from.isFresh === true,
    lastTool: typeof from.lastTool === 'string' ? from.lastTool : '',
    lastAt: typeof from.lastAt === 'number' ? from.lastAt : items.reduce((latest, item) => Math.max(latest, item.at), 0),
    recent: Array.isArray(from.recent) ? from.recent.filter((id): id is string => typeof id === 'string') : [],
    ...(from.sought === true ? { sought: true as const } : {}),
  }
}

/** "1 failed · 6 commands · edited draw.ts, png.ts +2" */
export const workLine = (work: Work): string => {
  const parts: string[] = []
  const count = (n: number, one: string, many: string): void => {
    if (n > 0) parts.push(n + ' ' + (n === 1 ? one : many))
  }
  // What failed is said first: the line is clipped from its end, and that is the last thing to lose.
  count(work.fails, 'failed', 'failed')
  count(work.cmds, 'command', 'commands')
  if (work.files.length > 0) parts.push('edited ' + work.files.join(', ') + (work.moreFiles > 0 ? ' +' + work.moreFiles : ''))
  else count(work.edits, 'edit', 'edits')
  count(work.reads, 'read', 'reads')
  count(work.agents, 'agent run', 'agent runs')
  count(work.other, 'other call', 'other calls')
  return parts.join(' · ')
}

files.hooks/view.ts:
// What the pane shows, as plain rows: the trail laid out for a width, before any element is made.
// Pure, so a test or the preview tool can read a page without a terminal.

import type { Beat, Item, ItemKind, Mode, OutputType, Picked, Question, Shot, Trail } from '../types'
import { clip, isOwnOutput, waitingCount, workCount, workLine } from './trail.ts'

/** What a press on a line jumps to: the transcript row it stands for, and a tool call beside it. */
export type Target = { id: string; anchor: string; alt?: string; kind: string }


/**
 * One entry of the pane, whatever the view. Every entry is drawn the same
 * way: a quiet row with its time and its actions in brackets, then what it
 * says under that, then its picture if it has one.
 */
export type Row =
  | { kind: 'day'; key: string; text: string }
  | {
      kind: 'line'
      key: string
      /** What `[go to conversation]` scrolls the transcript to. */
      target: Target
      time: string
      /** The mark before the words, or a space for an entry that has none (an update is read as a short piece). */
      glyph: string
      /** The words, wrapped: a few rows at rest, all of them once `[more]` is pressed. */
      lines: string[]
      /** Cells the words after the first row are set in by: the mark's width. */
      pad: number
      /** There is more to read than is shown: the entry has `[more]`, or `[less]` while it is all shown. */
      hasMore: boolean
      isOpen: boolean
      work: string
      /** Once the person has asked to go to the entry's place in the conversation: that it went, or why it did not. */
      note: string
      /** How the words are weighted: what was asked, something to be read, or an aside. */
      tone: 'ask' | 'plain' | 'quiet'
      /** An output's entry: the thing itself, for `[open]`. */
      open?: Shot
      /** A thing the work left for the person to do: what `[done]` stops waiting. */
      settles?: string
      /** And what they need to do it with: links to open and commands to copy. */
      refs?: string[]
    }
  | {
      kind: 'question'
      key: string
      question: Question
      time: string
      /** The question, wrapped. */
      lines: string[]
    }

export type Page = {
  rows: Row[]
  /** Entries older than the page shows, and newer. */
  earlier: number
  later: number
  foot: string
}

export type Look = {
  width: number
  picked: Picked
  page: number
  mode: Mode
  /** Minutes east of UTC where the person is. */
  zone: number
}

/** Lines to a page, and how far a page back moves: pages overlap so a place is not lost. */
export const PAGE_LINES = 120
export const PAGE_STEP = 80
/** Cells an entry's mark takes before its words, and that the rows under the first are set in by. */
const MARK = 2
/** The widest a line of text is set, in cells: wider is tiring to read. */
const MEASURE = 72
const NOBODYS = /^(Background task\b|Carried on without a new prompt$)/

const GLYPH: Record<ItemKind, string> = { ask: '❯', step: '•', done: '✓', shot: '▣', recap: '≡', compact: '~' }
/** Lines of a request or a step shown once it is opened, and of an update always: an update is there to be read whole. */
const DETAIL_OPEN = 12
const UPDATE_LINES = 12
/** Rows one action of an update may take, and the longest an update made of actions is when it is one line of text. */
const ACTION_LINES = 3
const ACTION_WIDEST = 110
const CAPTION_LINES = 6
const OUTPUT_GLYPH: Record<OutputType, string> = { image: '▣', video: '▶', file: '▤', link: '↗' }
const DAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']

const isWide = (code: number): boolean =>
  (code >= 0x1100 && code <= 0x115f) ||
  (code >= 0x2e80 && code <= 0xa4cf) ||
  (code >= 0xac00 && code <= 0xd7a3) ||
  (code >= 0xf900 && code <= 0xfaff) ||
  (code >= 0xfe30 && code <= 0xfe4f) ||
  (code >= 0xff00 && code <= 0xff60) ||
  (code >= 0xffe0 && code <= 0xffe6) ||
  (code >= 0x1f300 && code <= 0x1faff) ||
  (code >= 0x20000 && code <= 0x3fffd)

/** How many terminal cells a string takes, near enough to cut it by. */
export const cells = (text: string): number => {
  let count = 0
  for (const char of text) count += isWide(char.codePointAt(0) ?? 0) ? 2 : 1
  return count
}

const cutTo = (text: string, width: number): string => {
  let out = ''
  let used = 0
  for (const char of text) {
    const size = isWide(char.codePointAt(0) ?? 0) ? 2 : 1
    if (used + size > width) break
    out += char
    used += size
  }
  return out
}

/** Wraps at words into at most `max` lines of `width` cells; what does not fit ends in an ellipsis. */
export const wrap = (text: string, width: number, max: number): string[] => {
  const room = Math.max(4, width)
  const out: string[] = []
  let line = ''
  const words = text.split(' ').filter(Boolean)
  let index = 0
  for (; index < words.length; index++) {
    let word = words[index]!
    const joined = line ? line + ' ' + word : word
    if (cells(joined) <= room) {
      line = joined
      continue
    }
    if (line) {
      out.push(line)
      line = ''
      if (out.length === max) break
    }
    // A word wider than the line is broken across lines.
    while (cells(word) > room) {
      const piece = cutTo(word, room)
      out.push(piece)
      word = word.slice(piece.length)
      if (out.length === max) break
    }
    if (out.length === max) break
    line = word
  }
  if (line && out.length < max) {
    out.push(line)
    index = words.length
  }
  if (index < words.length && out.length > 0) {
    const last = out[out.length - 1]!
    out[out.length - 1] = (cells(last) >= room ? cutTo(last, room - 1) : last).replace(/[\s,;:.]+$/, '') + '…'
  }
  return out
}

/** Wrapped lines with a tail set after the last of them, the line cut to make room: how long a turn ran is said whatever the length of what was asked. */
const tailed = (lines: string[], tail: string, room: number): string[] => {
  if (!tail || lines.length === 0) return lines
  const last = lines[lines.length - 1]!
  const fits = cells(last) + 2 + cells(tail) <= room
  const kept = fits ? last : cutTo(last, Math.max(1, room - cells(tail) - 3)).replace(/[\s,;:.…]+$/, '') + '…'
  return [...lines.slice(0, -1), kept + '  ' + tail]
}

const local = (at: number, zone: number): Date => new Date(at + zone * 60_000)
const two = (n: number): string => String(n).padStart(2, '0')

export const clock = (at: number, zone: number): string => {
  const date = local(at, zone)
  return two(date.getUTCHours()) + ':' + two(date.getUTCMinutes())
}

const dayOf = (at: number, zone: number): string => {
  const date = local(at, zone)
  return DAYS[date.getUTCDay()]! + ' ' + MONTHS[date.getUTCMonth()]! + ' ' + date.getUTCDate()
}

/** "42s", "3m", "2h 05m", "1d 4h": how long something took, or how long ago it was. */
export const span = (ms: number): string => {
  const minutes = Math.round(ms / 60_000)
  if (minutes < 1) return Math.max(1, Math.round(ms / 1000)) + 's'
  if (minutes < 60) return minutes + 'm'
  const hours = Math.floor(minutes / 60)
  if (hours < 24) return hours + 'h ' + two(minutes % 60) + 'm'
  return Math.floor(hours / 24) + 'd ' + (hours % 24) + 'h'
}

/** "+0900" or "-1000", as `date +%z` prints it, in minutes east of UTC; undefined when it is neither. */
export const zoneOf = (text: string): number | undefined => {
  const found = /^([+-])(\d\d)(\d\d)$/.exec(text.trim())
  if (!found) return undefined
  return (found[1] === '-' ? -1 : 1) * (Number(found[2]) * 60 + Number(found[3]))
}

const counted = (count: number, one: string, many: string): string => count + ' ' + (count === 1 ? one : many)

const footOf = (trail: Trail, look: Look): string => {
  const prompts = trail.items.filter(item => item.kind === 'ask' && !NOBODYS.test(item.line)).length
  const unopened = (of: Item[]): string => {
    const left = of.filter(item => item.shot !== undefined && Boolean(item.shot.full || item.shot.file) && !item.shot.opened).length
    return left > 0 ? ` (${left} not opened)` : ''
  }
  const outputs = trail.items.filter(item => isOwnOutput(item, trail)).length
  const waiting = waitingCount(trail)
  const told = trail.feed.filter(beat => beat.kind !== 'built' && beat.kind !== 'waiting').length
  const parts =
    look.mode === 'questions'
      ? []
      : [look.mode === 'feed' ? counted(told, 'update', 'updates') : look.mode === 'outputs' ? counted(outputs, 'output', 'outputs') + unopened(trail.items.filter(item => isOwnOutput(item, trail))) : counted(prompts, 'prompt', 'prompts')]
  if (waiting > 0) parts.push(waiting + ' waiting on you')
  const last = Math.max(trail.lastAt, trail.items.reduce((latest, item) => Math.max(latest, item.at), 0))
  // The day, not how long ago: the pane may sit undrawn for a night, and an age would go stale in it.
  if (trail.isOpen) parts.push('working now')
  else if (last > 0) parts.push('quiet since ' + dayOf(last, look.zone) + ' ' + clock(last, look.zone))
  return parts.join(' · ')
}

type Entry = { at: number; rank: number; seq: number; row: () => Row }

/** Rows of an entry's words shown at rest and once opened, by what the entry is. */
const AT_REST: Record<ItemKind, number> = { ask: 3, step: 2, done: 4, shot: 1, recap: 8, compact: 1 }

export const layout = (trail: Trail, look: Look): Page => {
  // Text is set no wider than reads well, however wide the pane is drawn.
  const width = Math.max(16, Math.min(look.width, MEASURE))
  const isOpen = (id: string): boolean => look.picked.id === id && look.picked.isOpen === true
  const noteFor = (id: string): string => {
    if (look.picked.id !== id || look.picked.jump === undefined) return ''
    return look.picked.jump ? clip("can't go there: " + look.picked.jump, width) : 'the conversation is at this point now'
  }
  const timeOf = (at: number): string => (at > 0 ? clock(at, look.zone) : '--:--')
  const entries: Entry[] = []
  let seq = 0

  // The feed is the updates and nothing else: what was done, as it has been told. What was asked, and what the
  // work produced, are the other views'; a step no update tells of yet is not shown, the line under the tabs saying
  // that work is going on.
  for (const item of trail.items) {
    if (look.mode === 'questions' || look.mode === 'feed') break
    // The outputs are Claude's: what the session made, sent or published, not what the person showed it.
    if (look.mode === 'outputs' && !isOwnOutput(item, trail)) continue
    // The last view is the person's own side of the conversation: each thing they asked, and nothing of what was done about it.
    if (look.mode === 'steps' && (item.kind !== 'ask' || NOBODYS.test(item.line))) continue
    entries.push({
      at: item.at,
      rank: item.kind === 'ask' ? 0 : 1,
      seq: seq++,
      row: () => {
        const opened = isOpen(item.id)
        const isOutput = item.kind === 'shot'
        const room = Math.max(8, width - MARK)
        const took = item.kind === 'ask' && item.ms !== undefined && item.ms >= 60_000 ? '(' + span(item.ms) + ')' : ''
        // Opened, a request or a step shows all that was said; at rest, its first sentence.
        const rest = AT_REST[item.kind] ?? 2
        const name = item.line
        const atRest = wrap(name, room, rest)
        const whole = wrap(item.more ?? name, room, DETAIL_OPEN)
        const hasMore = whole.length > atRest.length || (item.more !== undefined && item.more.length > item.line.length) || (atRest.at(-1)?.endsWith('…') ?? false)
        const said = tailed(opened ? whole : atRest, took, room)
        // An output is told of too: what it shows and what it was about, under its name.
        const lines = item.shot?.note ? [...said, ...wrap(item.shot.note, room, CAPTION_LINES)] : said
        // Something to open that the person has not opened yet is new to them; opened, it is read.
        const canOpen = isOutput && item.shot !== undefined && Boolean(item.shot.full || item.shot.file)
        return {
          kind: 'line',
          key: item.id,
          target: { id: item.id, anchor: item.anchor, kind: item.kind, ...(item.alt ? { alt: item.alt } : {}) },
          time: timeOf(item.at),
          glyph: isOutput ? OUTPUT_GLYPH[item.shot?.type ?? 'image'] : (GLYPH[item.kind] ?? '•'),
          lines,
          pad: MARK,
          hasMore: hasMore && !isOutput,
          isOpen: opened,
          // In the feed the tally is noise; under a step it is what the step came to.
          work: look.mode === 'steps' && item.work && workCount(item.work) > 0 ? clip(workLine(item.work), Math.max(8, room - 2)) : '',
          note: noteFor(item.id),
          // A request is the person's; work a finished background task set off, or that simply carried on, is nobody's.
          tone: canOpen ? (item.shot!.opened ? 'quiet' : 'ask') : item.kind === 'ask' ? (NOBODYS.test(item.line) ? 'quiet' : 'ask') : item.kind === 'recap' || item.kind === 'compact' ? 'quiet' : 'plain',
          ...(canOpen ? { open: item.shot! } : {}),
        }
      },
    })
  }

  const beatRow = (beat: Beat): Row => {
    const isTask = beat.kind === 'built'
    const isWait = beat.kind === 'waiting'
    // A thing to do is a line with its mark. An update is its actions, each a short line of its own with a
    // mark; one written before updates were actions is a short piece, read across the whole pane.
    const pad = isTask || isWait ? MARK : 0
    const words = beat.detail ? beat.title + ' ' + beat.detail : beat.title
    const isActions = !isTask && !isWait && (words.includes('\n') || words.length <= ACTION_WIDEST)
    const lines = isActions
      ? words.split('\n').flatMap(action => wrap(action, Math.max(8, width - MARK), ACTION_LINES).map((text, index) => (index === 0 ? '• ' : '  ') + text))
      : wrap(words, width - pad, UPDATE_LINES)
    return {
      kind: 'line',
      key: beat.id,
      target: { id: beat.id, anchor: beat.anchor, kind: isTask ? 'task' : isWait ? 'wait' : 'update', ...(beat.alt ? { alt: beat.alt } : {}) },
      time: timeOf(beat.at),
      glyph: isTask ? '✓' : isWait ? '○' : ' ',
      lines,
      pad,
      hasMore: false,
      isOpen: false,
      work: '',
      note: noteFor(beat.id),
      tone: isTask || isWait ? 'ask' : 'plain',
      ...(isWait ? { settles: beat.id } : {}),
      ...(isWait && beat.refs && beat.refs.length > 0 ? { refs: beat.refs } : {}),
    }
  }
  if (look.mode === 'feed' || look.mode === 'questions') {
    for (const beat of trail.feed) {
      // A thing left with the person has a list of its own; the feed is the updates. (A big task done, which older versions listed, is no longer shown.)
      const isWait = beat.kind === 'waiting'
      if (isWait ? look.mode !== 'questions' || beat.over !== undefined : beat.kind === 'built' || look.mode === 'questions') continue
      // An update tells of what came before it, pictures included: it sits above them.
      entries.push({ at: beat.at, rank: 3, seq: seq++, row: () => beatRow(beat) })
    }
  }

  // A question asked and answered is a thing that happened: it is told among the steps, and nowhere else.
  for (const question of trail.questions) {
    if (question.answer === undefined || look.mode !== 'steps') continue
    const id = 'q:' + question.id
    entries.push({
      at: question.at,
      rank: 2,
      seq: seq++,
      row: () => {
        const room = Math.max(8, width - MARK)
        return {
          kind: 'line',
          key: id,
          target: { id, anchor: question.id, kind: 'question' },
          time: timeOf(question.at),
          glyph: '?',
          lines: [...wrap(question.text, room, 3), ...wrap('You: ' + question.answer, room, 3)],
          pad: MARK,
          hasMore: false,
          isOpen: false,
          work: '',
          note: noteFor(id),
          tone: 'plain',
        }
      },
    })
  }

  // The page reads from the latest back, strictly by the clock: what a request came to sits above the things
  // that happened in it, and the request itself below them, where it began. What has no time keeps its order.
  entries.sort((a, b) => (a.at && b.at ? a.at - b.at : 0) || a.rank - b.rank || a.seq - b.seq)
  entries.reverse()

  const total = entries.length
  const [size, step] = [PAGE_LINES, PAGE_STEP]
  const start = Math.min(Math.max(0, look.page) * step, Math.max(0, total - 1))
  const shown = entries.slice(start, start + size)
  const rows: Row[] = []
  // What waits on the person has a view of its own, there only while something waits: it is to be answered, not read past.
  if (look.mode === 'questions') {
    for (const question of [...trail.questions].reverse()) {
      if (question.answer !== undefined) continue
      rows.push({
        kind: 'question',
        key: 'q:' + question.id,
        question,
        time: timeOf(question.at),
        lines: wrap(question.text, width, 8),
      })
    }
  }
  let day = ''
  for (const entry of shown) {
    const today = dayOf(entry.at, look.zone)
    if (entry.at > 0 && today !== day) {
      day = today
      rows.push({ kind: 'day', key: 'day:' + entry.seq, text: today })
    }
    rows.push(entry.row())
  }

  return { rows, earlier: Math.max(0, total - start - shown.length), later: start, foot: footOf(trail, look) }
}

files.types/index.d.ts:
/** The work done under one step: what was called, what was edited, what failed. */
export type Work = {
  cmds: number
  reads: number
  edits: number
  agents: number
  other: number
  fails: number
  /** Basenames written or edited, oldest first, a few at most. */
  files: string[]
  /** How many more files were edited than `files` names, and which (a few at most), so one edited twice counts once. */
  moreFiles: number
  extra: string[]
  /** What the latest call said it was doing. */
  now: string
  /** What the calls said they were doing, oldest first, a few at most: what a highlight is written from. */
  notes: string[]
}

/** What an output is: a picture (when nothing says otherwise), a video, some other file handed over, or a page published. */
export type OutputType = 'image' | 'video' | 'file' | 'link'

/**
 * Something the work produced or looked at, kept for the trail: a small PNG
 * of the mod's own to draw in the pane (a video's or a document's is its
 * preview; `file` is empty where there is none), its shape, and the whole
 * thing to open: a file's path, or a page's address. A picture that is a
 * file on disk is not copied: `full` is the file itself and `stamp` when it
 * was last written as the picture was kept, so it is opened only while it
 * is still that picture, and the small PNG otherwise. `note` is its caption,
 * what it shows and what it was about: absent until the conversation has been
 * asked, empty when it had nothing to say. `guess` marks a caption written
 * from what was said around the picture by a model that did not see it
 * (which costs next to nothing): the conversation, which did see it, may
 * still be asked for a better one. `opened` is when the person last opened
 * it from the pane: what they have opened reads as read, the rest as new.
 * Nothing is drawn in the pane and nothing is copied: `file` is empty for
 * whatever the mod has kept since it stopped keeping pictures.
 */
export type Shot = { file: string; w: number; h: number; full?: string; stamp?: number; note?: string; guess?: true; opened?: number; type?: OutputType; from?: Source }

/**
 * Where a picture came from when it is not Claude's own work: the `person`
 * pasted it, or it is a file from `earlier` than the session that Claude only
 * looked at. Absent, it is something the session made, sent or published.
 */
export type Source = 'person' | 'earlier'

/**
 * What a step is: the person's `ask`, a `step` the model narrated, the turn's
 * `done` line, a picture (`shot`), the engine's `recap` of where things
 * stand, or a mark where the context was compacted.
 */
export type ItemKind = 'ask' | 'step' | 'done' | 'shot' | 'recap' | 'compact'

/** One thing the conversation holds, as it happened: the layer the highlights are written from, and shown under them on request. */
export type Item = {
  /** Unique in the trail. */
  id: string
  /** The transcript row a click scrolls to: the row's id, or a tool call's. */
  anchor: string
  /** A tool call beside the row, tried when the row itself will not scroll. */
  alt?: string
  kind: ItemKind
  /** Milliseconds since the epoch. */
  at: number
  turn: number
  line: string
  /** More of what was said than its first sentence, kept until a highlight has been written from it. */
  more?: string
  work?: Work
  shot?: Shot
  /** On an ask: how long its turn ran, once it has ended. */
  ms?: number
  /** A highlight has been written that covers this. */
  fed?: true
}

/**
 * An update of the feed is a `summary`: a short account of a stretch of work.
 * A big task brought to a finish is `built`: it is what the list of things
 * done holds. The other kinds are from when the feed listed single things
 * that happened: something `built` or changed,
 * something `found` out, something `decided`, a `problem` met, one `fixed`,
 * something `checked` and how it came out, something `asked` of the person
 * (it waits on them), or a plain `note`. A `summary` is not one thing but
 * what a whole request came to, in a few sentences. Something `waiting` is
 * not a telling at all: it is a thing the work left for the person to do,
 * listed apart until it is done.
 */
export type BeatKind = 'summary' | 'built' | 'waiting' | 'found' | 'decided' | 'problem' | 'fixed' | 'checked' | 'asked' | 'note'

/** One update of the feed: what was done in a stretch of work and what came of it, in a few sentences, tied to the row where the stretch ended. */
export type Beat = {
  id: string
  /** The step it tells of. */
  ref: string
  turn: number
  /** When the step it tells of happened. */
  at: number
  kind: BeatKind
  /** The update's text. */
  title: string
  /** More of it, where an older kind kept a headline apart from its telling. */
  detail: string
  /** The transcript row a click scrolls to, and a tool call beside it. */
  anchor: string
  alt?: string
  /** Of something waiting on the person: when it stopped waiting, done or no longer needed. Absent while it waits. */
  over?: number
  /** Of something waiting on the person: what they need to do it with, in order. A link to open (it begins `http`), or a command to run, which is only ever copied. */
  refs?: string[]
}

/**
 * Something Claude asked the person in the pane, with the picture it is about
 * when there is one. It waits there until answered; the answer goes back to
 * the conversation as the person's next message.
 */
export type Question = {
  /** The tool call that asked it, which is also the transcript row a click scrolls to. */
  id: string
  at: number
  text: string
  /** Answers offered as buttons; the person may always type their own. */
  options: string[]
  shot?: Shot
  answer?: string
  answeredAt?: number
}

export type Trail = {
  items: Item[]
  /** The feed's updates, oldest first. */
  feed: Beat[]
  questions: Question[]
  turn: number
  /** A turn is running. */
  isOpen: boolean
  /** The newest ask has seen no turn end yet, so work that follows is its own. */
  isFresh: boolean
  /** The latest tool call's id. */
  lastTool: string
  /** When the latest thing happened: where a turn that was never seen to end is taken to have stopped. */
  lastAt: number
  /** Tool calls already counted, newest last: an event seen twice counts once. */
  recent: string[]
  /**
   * Its updates are written by a model that also looks for what waits on the
   * person. Absent on a trail told before the mod looked for that: the latest
   * of such a trail is read once more.
   */
  sought?: true
}

/** The trail as kept in the session's state and in its file; `v` is the shape's, so one kept by older code is read back from the transcript instead. */
export type Saved = { v: 5; sid: string; trail: Trail }

/**
 * The entry the person last pressed an action of. `isOpen`: they asked for
 * more of it, and it shows all it has. `jump` is what came of going to it in
 * the conversation: absent until they ask, '' once it landed, else why it did
 * not.
 */
export type Picked = { id: string; jump?: string; isOpen?: boolean }

/**
 * What the pane lists: the feed of updates (its highlights), everything the
 * work produced, each thing the person asked (`steps`, shown as "every
 * prompt"), or what waits on the person (`questions`: the questions Claude
 * put to them in the pane and the things the work left for them to do), which
 * is a view only while something does.
 */
export type Mode = 'feed' | 'outputs' | 'steps' | 'questions'

declare module 'claude-code' {
  interface PluginState {
    trail: {
      saved: Saved
      picked: Picked
      /** How many pages back from the newest lines the pane shows. */
      page: number
      mode: Mode
      /** How the writing of updates is going, when there is something to say about it. */
      status: string
    }
  }
}
